 41→  padding: gt.$section-padding;
 42→
 43→  &__grid {
 44→    display: grid;
 45→    grid-template-columns: repeat(auto-fit, minmax(250px, 1fr));
 46→    gap: gt.$feature-grid-gap;
 47→    max-width: gt.$max-width;
 48→    margin: 0 auto;
 49→  }
 50→
 51→  &__heading {
 52→    text-align: center;
 53→    font-size: gt.$feature-heading-size;
 54→    font-weight: 700;
 55→    color: var(--gt-primary);
