 64→    border-radius: gt.$border-radius;
 65→    padding: gt.$card-padding;
 66→    box-shadow: var(--gt-card-shadow);
 67→    transition:
 68→      transform gt.$transition-base,
 69→      box-shadow gt.$transition-base;
 70→    animation: fadeInUp 0.6s ease-out both;
 71→
 72→    @for $i from 1 through 4 {
 73→      &:nth-child(#{$i}) {
 74→        animation-delay: #{0.05 + $i * 0.1}s;
 75→      }
 76→    }
 77→
